// ---------- dropdown menu (Liner's DropdownMenu) ----------
let menuEl = null;
function closeMenu() { menuEl?.remove(); menuEl = null; }
function menu(list, x, y) {
  closeMenu();
  menuEl = document.createElement('div');
  menuEl.className = 'dm';
  menuEl.setAttribute('role', 'menu');
  menuEl.innerHTML = list.map((m, i) => `<button role="menuitem" data-i="${i}" class="${m.cls ?? ''}">${lu(m.icon)}<span>${esc(m.label)}</span></button>`).join('');
  document.body.append(menuEl);
  const r = menuEl.getBoundingClientRect();
  menuEl.style.left = `${Math.max(8, Math.min(x, innerWidth - r.width - 8))}px`;
  menuEl.style.top = `${y + r.height > innerHeight - 8 ? Math.max(8, y - r.height - 8) : y}px`;
  menuEl.addEventListener('click', e => {
    const b = e.target.closest('button');
    if (!b) return;
    closeMenu();
    list[b.dataset.i].on();
  });
  menuEl.querySelector('button')?.focus();
}
addEventListener('mousedown', e => { if (menuEl && !menuEl.contains(e.target)) closeMenu(); }, true);
addEventListener('keydown', e => { if (e.key === 'Escape' && menuEl) { e.stopPropagation(); closeMenu(); } }, true);
addEventListener('blur', closeMenu);

const liked = t => lib.liked.some(x => x.id === t.id);
const like = t => api.libDo(liked(t) ? 'unlike' : 'like', liked(t) ? t.id : t);
