      f.querySelector('.cp-desc').onclick = e => { e.currentTarget.outerHTML = `<textarea name="d" rows="2" maxlength="300" placeholder="${L('Aprašymas (nebūtinas)', 'Description (optional)')}"></textarea>`; f.querySelector('textarea').focus(); };
